package com.my.kizzy.feature_rpc_base.utils

import android.service.notification.StatusBarNotification

/**
 * Parses media metadata from system notifications generated by music players
 * (Spotify, YouTube Music, Apple Music, etc.) and alternative/modded clients
 * (SimpMusic, Meld, YMusic, ReVanced, etc.).
 *
 * Many alternative/modded clients don't register standard MediaSession tokens,
 * so their metadata can only be reliably scraped directly from notification extras.
 */
class MediaMetadataParser {

    // Known package name identifiers for popular music apps
    private val PKG_SPOTIFY = "com.spotify.music"
    private val PKG_YT_MUSIC = "com.google.android.apps.youtube.music"
    private val PKG_YOUTUBE = "com.google.android.youtube"
    private val PKG_APPLE_MUSIC = "com.apple.android.music"
    private val PKG_KKBOX = "com.kkbox.player"
    private val PKG_STREETVOICE = "com.streetvoice.music"
    private val PKG_YMURIC = "y.music"

    data class ParsedTrack(
        val title: String,
        val artist: String,
        val album: String?,
        val packageName: String
    )

    /**
     * Extracts track metadata from a notification posted by a media player.
     *
     * Handles both official apps (Spotify, YouTube Music, Apple Music) and
     * alternative/modded clients (SimpMusic, Meld, ReVanced, YMusic, etc.)
     * where metadata may only be available via notification extras.
     */
    fun extractFromNotification(sbn: android.service.notification.StatusBarNotification): ParsedTrack? {
        val packageName = sbn.packageName
        val extras = sbn.notification.extras

        val title = extras.getString(android.app.Notification.EXTRA_TITLE)
        val text = extras.getString(android.app.Notification.EXTRA_TEXT) // Usually artist or album info

        if (title.isNullOrBlank()) return null

        val artist = when (packageName) {
            PKG_SPOTIFY, PKG_YT_MUSIC, PKG_APPLE_MUSIC, PKG_KKBOX -> {
                text ?: "Unknown Artist"
            }
            else -> {
                // Fallback for custom, modded, or alternative apps (SimpMusic, Meld, YMusic, etc.)
                // Often text contains the artist or channel name
                text ?: "Unknown Artist"
            }
        }

        return ParsedTrack(
            title = title,
            artist = artist,
            album = null,
            packageName = packageName
        )
    }

    fun isSupportedMediaApp(pkg: String): Boolean {
        return pkg.contains("spotify") ||
            pkg.contains("youtube") ||
            pkg.contains("apple.music") ||
            pkg.contains("kkbox") ||
            pkg.contains("streetvoice") ||
            pkg.contains("simpmusic") ||
            pkg.contains("meld") ||
            pkg.contains("ymusic") ||
            pkg.contains("morphe")
    }
}
